+                        (BYTE, _)    => mem_write_value(addr, 1, result[7..0],  aq & rl, rl, true),
+                        (HALF, _)    => mem_write_value(addr, 2, result[15..0], aq & rl, rl, true),
+                        (WORD, _)    => mem_write_value(addr, 4, result[31..0], aq & rl, rl, true),
